import React, { useEffect, useRef, useState } from "react";
import { Chart, registerables } from 'chart.js';


const BarChart = () => {
  const chartRef = useRef(null);
  const [chartData, setChartData] = useState(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const response = await fetch("http://localhost:5206/api/BloodRL/predict");
        if (response.ok) {
          const data = await response.json();
          setChartData(data);
        } else {
          console.error("Failed to fetch data:", response.status, response.statusText);
        }
      } catch (error) {
        console.error("An error occurred while fetching data:", error);
      }
    };

    fetchData();
  }, []);

  useEffect(() => {
    if (chartData) {
      // Extracting data for the chart
      const labels = Object.keys(chartData);
      const datasets = Object.values(chartData).map((hospitalData) => ({
        label: hospitalData[9].hospitalName,
        data: Object.values(hospitalData).map((item) => item.actualAvailability),
        backgroundColor: "rgba(75,192,192,0.2)",
        borderColor: "rgba(75,192,192,1)",
        borderWidth: 1,
      }));

      // Creating the chart
      const ctx = chartRef.current.getContext("2d");
      new Chart(ctx, {
        type: "bar",
        data: {
          labels,
          datasets,
        },
        options: {
          scales: {
            y: {
              beginAtZero: true,
            },
          },
        },
      });
    }
  }, [chartData]);

  return <canvas ref={chartRef} />;
};

export default BarChart;
